Plate mainCourse() throws InterruptedException {
    try (var scope = StructuredTaskScope.open()) {          // default: fail on the first failure
        Subtask<Roast> roast = scope.fork(() -> kitchen.roast());
        Subtask<Potatoes> potatoes = scope.fork(() -> kitchen.potatoes());
        scope.join();         // waits; throws StructuredTaskScope.FailedException if a subtask failed
        return new Plate(roast.get(), potatoes.get());
    }                         // close() cancels unfinished subtasks and waits for them
}

