class Dishwasher(dispatcher: CoroutineDispatcher) {
    private val scope = CoroutineScope(dispatcher + Job())

    fun wash(load: String): Job =
        scope.launch { runCycle(load) }

    suspend fun close() {
        scope.coroutineContext.job.cancelAndJoin()
    }
}

