// Java equivalent: the dishwasher owns an executor and shuts it down
class Dishwasher implements AutoCloseable {
    private final ExecutorService pool = Executors.newVirtualThreadPerTaskExecutor();

    Future<?> wash(String load) {
        return pool.submit(() -> runCycle(load));
    }

    @Override public void close() throws InterruptedException {
        pool.shutdownNow();                          // interrupt the loads still washing
        pool.awaitTermination(30, TimeUnit.SECONDS); // wait until they have stopped
    }
}

